import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC4", "RC2", "Blowfish", "MD5", "SHA1", "sha1", "md5"}
weak_protocols := {"TLSv1", "TLSv1.1", "SSLv3", "TLS1_0", "TLS1_1", "SSLv2", "TLSv1.0"}
disabled_values := {"false", "disabled", "none", "off", "no"}
legacy_terms := {"legacy", "backward_compatible", "backward compatible", "compatibility_mode", "compatibility mode"}

is_weak_algorithm(value) {
    value.ir_type == "String"
    algo := lower(value.value)
    weak_algorithms[_] == algo
}

is_weak_algorithm(value) {
    value.ir_type == "String"
    regex.match("(?i)(des|3des|rc4|rc2|blowfish|md5|sha1)", value.value)
}

is_small_key_size(attr_name, value) {
    value.ir_type == "Integer"
    bits := value.value
    regex.match("(?i)(rsa|dsa|ec|key)", attr_name)
    bits < 2048
}

is_small_key_size(attr_name, value) {
    value.ir_type == "Integer"
    bits := value.value
    regex.match("(?i)(key|symmetric|aes)", attr_name)
    bits < 128
}

is_weak_protocol(value) {
    value.ir_type == "String"
    weak_protocols[_] == value.value
}

is_weak_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)(ssl|tlsv?1[^2]|tlsv?1\\.[^2]|tls_1_[^2])", value.value)
    not regex.match("(?i)(tlsv?1\\.?[23]|tls_1_[23])", value.value)
}

is_disabled_encryption(attr_name, value) {
    value.ir_type == "Boolean"
    value.value == false
    regex.match("(?i)(encrypt|ssl|tls)", attr_name)
}

is_disabled_encryption(attr_name, value) {
    value.ir_type == "String"
    disabled_values[_] == lower(value.value)
    regex.match("(?i)(encrypt|ssl|tls)", attr_name)
}

is_legacy_crypto(value) {
    value.ir_type == "String"
    legacy := legacy_terms[_]
    regex.match(sprintf("(?i).*%s.*", [legacy]), value.value)
}

has_encryption_keyword(attr_name) {
    regex.match("(?i)(encryption|cipher|crypto|algorithm|kms_key|master_key|key_id)", attr_name)
}

has_tls_keyword(attr_name) {
    regex.match("(?i)(tls|ssl|protocol|version|policy)", attr_name)
}

has_key_keyword(attr_name) {
    regex.match("(?i)(key_size|key_length|bits|key_bits|rsa_key|minimum_tls)", attr_name)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    has_encryption_keyword(attr.name)
    is_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Weak cryptographic algorithm used - Avoid using deprecated or weak cryptographic algorithms. (CWE-326)"
    }
