weak_protocols := {"TLSv1", "TLSv1.1", "SSLv3", "TLS1_0", "TLS1_1", "SSLv2", "TLSv1.0", "TLS", "SSL"}
disabled_values := {"false", "disabled", "none", "off", "no"}
legacy_terms := {"legacy", "backward_compatible", "backward compatible", "compatibility_mode", "compatibility mode"}

# Extract all expressions recursively from nested structures
all_expressions(node) = exprs {
    exprs = {n |
        walk(node, [_, n])
        n.ir_type == "String"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "Integer"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "Boolean"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "FunctionCall"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "VariableReference"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "Array"
    } | {n |
        walk(node, [_, n])
        n.ir_type == "Hash"
    }
}

# Check if any expression contains weak algorithm
contains_weak_algorithm(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "des")
} else {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "md5")
} else {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "sha1")
} else {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "rc4")
} else {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "rc2")
} else {
    walk(node, [_, n])
    n.ir_type == "String"
    algo := lower(n.value)
    contains(algo, "blowfish")
}

# Check function calls for weak algorithms (Ansible filters)
is_weak_function_call(node) {
    node.ir_type == "FunctionCall"
    contains(lower(node.name), "hash")
    some arg
    arg := node.args[_]
    arg.ir_type == "String"
    contains_weak_algorithm_in_string(arg.value)
}

contains_weak_algorithm_in_string(str) {
    contains(lower(str), "sha1")
}

contains_weak_algorithm_in_string(str) {
