}

# Check arrays for weak algorithms
array_contains_weak_algorithm(arr) {
    arr.ir_type == "Array"
    some elem
    elem := arr.value[_]
    walk(elem, [_, n])
    n.ir_type == "String"
    contains_weak_algorithm_in_string(n.value)
}

is_small_key_size(attr_name, value) {
