}

has_cipher_keyword(attr_name) {
    regex.match("(?i)cipher", attr_name)
}

# Search all key-value pairs recursively in complex structures
search_all_key_values(node) = kvs {
    kvs = {{"name": k.name, "value": k.value, "line": k.line, "ir_type": k.ir_type} |
        walk(node, [_, k])
        k.ir_type == "Attribute"
    } | {{"name": k.name, "value": k.value, "line": k.line, "ir_type": k.ir_type} |
        walk(node, [_, k])
        k.ir_type == "Variable"
    } | {{"name": n.value, "value": v, "line": k.line, "ir_type": k.ir_type} |
        walk(node, [_, k])
        k.ir_type == "Hash"
        some pair
        pair := k.value[_]
        n := pair.key
        v := pair.value
        n.ir_type == "String"
    }
}

# Get direct attributes from atomic units
get_direct_attributes(node) = attrs {
    node.ir_type == "AtomicUnit"
    attrs = {{"name": a.name, "value": a.value, "line": a.line, "ir_type": a.ir_type} |
        a := node.attributes[_]
    }
} else = attrs {
    attrs = set()
}

# Main analysis entry point
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Search in all possible locations
    collected := search_all_key_values(parent)

    kv := collected[_]

    # Check for weak algorithm in value
    contains_weak_algorithm(kv.value)

    result := {
        "type": "sec_weak_crypt",
        "element": {"ir_type": kv.ir_type, "line": kv.line, "name": kv.name, "value": kv.value},
        "path": parent.path,
        "description": "Weak cryptographic algorithm used - Avoid using deprecated or weak cryptographic algorithms. (CWE-326)"
    }
}

